//! komga tool surface.
//!
//! Endpoint registry: `komga.{list, detail, create, update, delete}` —
//! generated by `#[endpoint_resource]`.
//!
//! Library upkeep:
//!   - `komga.library.audit`   mis-numbered books, duplicates, misfiled/unparseable files, gaps
//!   - `komga.books.renumber`  write filename issue numbers back, locked (dry run by default)
//!   - `komga.books.dedupe`    delete duplicate (and optionally generic) files (dry run by default)
//!   - `komga.library.scan`    trigger a library scan (dry run by default)
//!   - `komga.readlist.sync`   create or rewrite an ordered readlist (dry run by default)
//!   - `komga.series.metadata` read a series' metadata and locked fields
//!   - `komga.series.metadata_set` set series metadata fields, locked (dry run by default)
//!
//! Libraries default to the one named `comics`: the filename rules are comic
//! conventions and would misread manga chapters.

use std::collections::{BTreeMap, BTreeSet};

use plugin_toolkit::prelude::*;

use crate::api::{check_id, Komga, Library, ReadList};
use crate::audit::{
    self, AuditReport, DedupeGroup, DedupeLoser, LibraryData, OrphanIssue, Renumber, Skipped,
};
use crate::execute;
use crate::readlist::{
    self, Catalog, ReadlistDiff, ReadlistEntry, ResolvedEntry, SeriesMatch, UnresolvedEntry,
};
use crate::series_meta::{self, SeriesMetadataView, Wanted};

#[endpoint_resource(plugin = "komga")]
pub struct KomgaEndpoint {
    pub name: String,
    /// Komga API key, sent as `X-API-Key`.
    #[secret]
    pub api_key: String,
    /// Skip TLS verification (self-signed certs).
    pub insecure: bool,
    pub enabled: bool,
}

pub async fn connect(name: &str) -> Result<Komga> {
    let row = endpoint_db::require(name)?;
    let api_key = plugin_toolkit::secrets::resolve_scoped("komga", name, "api_key")?;
    let base_url = route::resolve_reachable(name, &row.routes, row.insecure).await?;
    Komga::new(&base_url, api_key.expose_secret(), row.insecure)
}

/// Auto-selected only when named exactly `comics`/`comic`, so a mixed
/// library (`Comics & Manga`) is never picked up silently.
fn is_comics(l: &Library) -> bool {
    matches!(l.name.trim().to_lowercase().as_str(), "comics" | "comic")
}

/// Libraries in scope: one library, or the comics libraries.
async fn libraries_in_scope(k: &Komga, library_id: Option<&str>) -> Result<Vec<Library>> {
    if let Some(lid) = library_id {
        return Ok(vec![k.library(lid).await?]);
    }
    let libs: Vec<Library> = k.libraries().await?.into_iter().filter(is_comics).collect();
    if libs.is_empty() {
        bail!("no library is named \"comics\"; pass a library id");
    }
    Ok(libs)
}

async fn collect(
    k: &Komga,
    library_id: Option<&str>,
    series_id: Option<&str>,
) -> Result<Vec<LibraryData>> {
    match (library_id, series_id) {
        (Some(_), Some(_)) => bail!("pass a library id or a series id, not both"),
        (_, Some(sid)) => {
            let series = k.series(sid).await?;
            Ok(vec![LibraryData {
                library: k.library(&series.library_id).await?,
                books: k.series_books(sid).await?,
                series: vec![series],
            }])
        }
        (lid, None) => {
            let mut out = Vec::new();
            for library in libraries_in_scope(k, lid).await? {
                out.push(LibraryData {
                    series: k.library_series(&library.id).await?,
                    books: k.library_books(&library.id).await?,
                    library,
                });
            }
            Ok(out)
        }
    }
}

/// Mutating verbs act on an explicit scope; `all` means the comics libraries.
fn require_scope(
    tool: &str,
    library_id: &Option<String>,
    series_id: &Option<String>,
    all: bool,
) -> Result<()> {
    if library_id.is_none() && series_id.is_none() && !all {
        bail!("{tool}: pick a scope: library_id, series_id, or all");
    }
    Ok(())
}

#[orca_struct]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Failure {
    pub id: String,
    pub error: String,
}

