// komga.library.audit
// ═══════════════════════════════════════════════════════════════════════════

#[orca_struct(args)]
pub struct AuditArgs {
    /// Registered komga endpoint name.
    #[arg(long)]
    pub name: String,
    /// Komga library id. Omitted, the library named `comics`.
    #[arg(long)]
    pub library_id: Option<String>,
    /// Komga series id, to audit one series.
    #[arg(long)]
    pub series_id: Option<String>,
}

/// Read-only audit of comic numbering. Komga numbers books by sort order, not
/// by the number in the filename, so series with gaps read out of order. Per
/// series: books whose Komga number differs from the filename's, books sharing
/// a number, files that look like another series, files with no number,
/// edge cases (decimal/suffixed issues, volumes, collected editions in an
/// issue series), and missing issue ranges.
#[orca_tool(domain = "komga", verb = "library.audit", role = "read")]
async fn komga_library_audit(args: AuditArgs, _ctx: &ToolCtx) -> Result<AuditReport> {
    let k = connect(&args.name).await?;
    let data = collect(&k, args.library_id.as_deref(), args.series_id.as_deref()).await?;
    Ok(audit::audit(&args.name, &data))
}

